import{iconArt}from'./vector-primitives.mjs';
const ink='#171717',esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const rect=(x,y,w,h,fill,r=12)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${fill}" stroke="${ink}" stroke-width="4"/>`;
const line=(d,color=ink,w=5)=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const coin=(x,y,r=11)=>`<g data-object="coin"><circle cx="${x}" cy="${y}" r="${r}" fill="#ffe35e" stroke="${ink}" stroke-width="3"/><circle cx="${x}" cy="${y}" r="${r*.7}" fill="none" stroke="#cb9822" stroke-width="2"/></g>`;
const arrow=(d,tip,color)=>`<g data-object="flow-arrow">${line(d,'#fff',15)}${line(d,color,9)}<path d="${tip}" fill="${color}" stroke="${ink}" stroke-width="2" stroke-linejoin="round"/></g>`;
function bot(x,y,s=1,color='#7acff5'){return `<g data-object="robot" transform="translate(${x} ${y}) scale(${s})">${rect(-29,-25,58,48,color,19)}${rect(-20,-15,40,23,'#15285b',10)}<ellipse cx="-8" cy="-4" rx="4" ry="7" fill="#e6ffff"/><ellipse cx="8" cy="-4" rx="4" ry="7" fill="#e6ffff"/>${rect(-24,27,48,36,color,16)}${line('M-10 66L-18 76M10 66L18 76')}<circle cx="-34" cy="45" r="8" fill="${color}" stroke="${ink}" stroke-width="3"/><circle cx="34" cy="45" r="8" fill="${color}" stroke="${ink}" stroke-width="3"/></g>`}
function platform(x,y,color,kind,label){return `<g data-platform="${kind}" transform="translate(${x} ${y})"><ellipse cx="103" cy="149" rx="105" ry="37" fill="${color}" stroke="${ink}" stroke-width="4"/><ellipse cx="103" cy="138" rx="105" ry="31" fill="${color}" stroke="${ink}" stroke-width="3"/><g transform="translate(24 12)">${iconArt(kind).replace('<svg ','<svg x="0" y="0" width="164" height="129" ')}</g>${bot(25,118,.38,color)}${label?`<text x="106" y="169" text-anchor="middle" font-size="18" font-weight="850">${esc(label)}</text>`:''}${kind==='engage'?`<path d="M137 83H192L178 112V135L153 148V112Z" fill="#ad96ff" stroke="${ink}" stroke-width="3"/>`:''}${kind==='monetize'?coin(163,127,14)+coin(185,141,12):''}</g>`}
/** Four platform groups and central four-arm robot; all arrows remain static. */
export function robotLoopSvg({brand='',labels=['创作','发布','互动','变现'],colors={}}={}){const p={create:'#ffe35e',publish:'#ff9fca',engage:'#ad96ff',monetize:'#c7f125',core:'#7acff5',...colors};return `<svg viewBox="0 0 600 520" aria-hidden="true" data-diagram="robot-loop">${arrow('M189 97Q292 43 405 94','M399 77L422 99L393 108',p.create)}${arrow('M539 183Q585 251 548 326','M535 316L544 344L564 323',p.publish)}${arrow('M412 440Q297 492 188 441','M196 426L170 438L190 454',p.engage)}${arrow('M66 327Q14 258 57 186','M42 197L62 170L74 200',p.monetize)}${platform(10,29,p.create,'create',labels[0])}${platform(382,29,p.publish,'publish',labels[1])}${platform(382,309,p.engage,'engage',labels[2])}${platform(10,309,p.monetize,'monetize',labels[3])}<g data-object="central-four-arm-links">${line('M279 231L211 161M320 231L391 161M279 281L211 363M320 281L392 365','#fff',20)}${line('M279 231L211 161M320 231L391 161M279 281L211 363M320 281L392 365',p.core,12)}</g><ellipse cx="300" cy="286" rx="83" ry="39" fill="#2759bf" stroke="${ink}" stroke-width="4"/><ellipse cx="300" cy="272" rx="83" ry="34" fill="${p.core}" stroke="${ink}" stroke-width="4"/><ellipse cx="300" cy="267" rx="58" ry="23" fill="none" stroke="#fff" stroke-width="5"/>${bot(300,218,1.05,p.core)}${brand?`<text x="300" y="328" text-anchor="middle" font-size="20" font-weight="850">${esc(brand)}</text>`:''}</svg>`}
function people(x,y){return `<g data-object="audience" transform="translate(${x} ${y})">${[0,1,2,3].map((i)=>`<g transform="translate(${i*33} ${i%2*15})"><circle cy="-20" r="15" fill="#f4d7b2" stroke="${ink}" stroke-width="3"/><path d="M-20 45V8Q0-12 20 8V45Z" fill="${['#ff9fca','#7acff5','#c7f125','#ad96ff'][i]}" stroke="${ink}" stroke-width="3"/></g>`).join('')}<path d="M18-58H72V-30H43L30-15V-30H18Z" fill="#fff" stroke="${ink}" stroke-width="3"/></g>`}
/** Distinct outro pipeline: edit -> person/laptop/robot -> publishing/growth -> audience/deal. */
export function outroLineSvg({actorSrc=null,brand='',colors={}}={}){const p={paper:'#fff5da',create:'#7acff5',publish:'#ff9fca',growth:'#ffe35e',engage:'#ad96ff',...colors};return `<svg viewBox="0 0 900 500" style="display:block;width:100%;height:100%" aria-hidden="true" data-diagram="outro-line"><rect width="900" height="500" fill="${p.paper}"/><g data-object="storyboard">${rect(15,12,228,134,'#fff')}${[0,1,2,3].map(i=>rect(25+i%2*107,22+Math.floor(i/2)*58,96,49,i%2?'#ffdfb5':'#b8def5',3)+line(`M${34+i%2*107} ${60+Math.floor(i/2)*58}l25-23 22 15 15-14 16 22`,ink,3)).join('')}</g><g data-object="camera">${rect(18,198,125,76,'#252c36',9)}${rect(41,185,49,20,'#4f5967',4)}<ellipse cx="143" cy="236" rx="34" ry="43" fill="#363a43" stroke="${ink}" stroke-width="4"/><ellipse cx="153" cy="236" rx="22" ry="32" fill="${p.create}" stroke="${ink}" stroke-width="4"/>${line('M70 276L35 328M70 276L100 328')}</g><g data-object="edit-screen">${rect(15,336,248,145,'#252c36',5)}${rect(29,348,220,66,'#87bfe3',3)}${[0,1,2].map(i=>rect(32+i*72,357,63,47,['#ff9fca','#ffe35e','#ad96ff'][i],2)).join('')}${[0,1,2].map(i=>line(`M29 ${431+i*16}H248`,['#7acff5','#ff9fca','#c7f125'][i],9)).join('')}</g>${arrow('M194 245Q261 223 320 264','M303 252L335 269L302 279',p.create)}${arrow('M414 213Q517 145 613 151','M596 133L633 149L598 169',p.publish)}${arrow('M449 346Q559 373 650 397','M634 379L668 402L632 413',p.engage)}<g data-object="actor-slot">${actorSrc===null?'':`<image href="${esc(actorSrc)}" x="273" y="98" width="289" height="268" preserveAspectRatio="xMidYMid meet"/>`}</g><g data-object="laptop">${rect(325,311,211,129,'#576172',9)}<path d="M339 425H521L550 454H312Z" fill="#929da9" stroke="${ink}" stroke-width="4"/><circle cx="430" cy="368" r="27" fill="${p.create}" stroke="${ink}" stroke-width="3"/>${brand?`<text x="430" y="374" text-anchor="middle" font-size="13" font-weight="850">${esc(brand)}</text>`:''}</g>${bot(284,406,.68,'#fff')}<g data-object="calendar">${rect(566,17,158,145,'#fff',8)}${rect(566,17,158,30,p.publish,8)}${[0,1,2,3,4,5,6,7,8].map(i=>rect(578+i%3*46,59+Math.floor(i/3)*30,35,23,['#fff','#7acff5','#ff9fca'][i%3],2)).join('')}</g><g data-object="platform-growth">${[0,1,2].map(i=>rect(744+i*45,20,36,36,['#ff9fca','#7acff5','#ad96ff'][i],7)).join('')}${[0,1,2,3].map(i=>rect(749+i*32,172-i*27,23,43+i*27,p.growth,1)).join('')}${line('M742 151L865 76',p.publish,8)}<path d="M846 76H865V95" fill="none" stroke="${ink}" stroke-width="4"/>${coin(771,241,20)}${coin(815,236,24)}${coin(857,232,20)}</g>${people(602,390)}<g data-object="handshake-deal"><path d="M759 348L788 330L817 350L840 330L876 352L861 375L833 365L811 378L788 365Z" fill="#efca9a" stroke="${ink}" stroke-width="4"/>${line('M813 351L835 365M805 359L821 372',ink,3)}${rect(747,376,48,92,p.create,7)}${rect(838,376,48,92,p.engage,7)}${coin(815,459,18)}</g><g data-object="audience-funnel"><path d="M577 445H702L671 468V483H608V468Z" fill="${p.engage}" stroke="${ink}" stroke-width="3"/></g></svg>`}
